/**
 * Build-time compilation of the lesson-schema validator (#2205).
 *
 * `ajv.compile()` at runtime generates the validator via `new Function` -
 * an `unsafe-eval` CSP violation that broke /content under the fixed
 * policy. Ajv supports standalone code generation instead: this script
 * compiles the pinned schema mirror ONCE and writes a plain-function
 * module; the bundle then contains zero runtime code generation.
 *
 * Coupling to the schema pin: the generated file embeds the sha256 of the
 * schema source it was built from. A re-pin without regeneration is caught
 * by the drift test (lesson-schema-validator.standalone.test.ts), never
 * silent. Regenerated by `bun run generate:validator` (wired into
 * `make sync-schema`).
 *
 * Output is native ESM (#2288): a `.mjs` with `export default`. Ajv's
 * `code.esm` converts the EXPORT, but (ajv 8.x) leaves its inline runtime
 * helpers as `const x = require(...)` — which the Vite DEV SERVER serves raw
 * to the browser, where `require`/`module.exports` are undefined and the
 * import fails with "does not provide an export named 'default'". The
 * production bundler applied CJS interop and hid this, so a `.cjs` shipped
 * green for two release cycles while `make dev` (and the API-mode smoke) were
 * broken. We therefore hoist those inline requires to top-level ESM imports
 * and fail closed if any `require(` survives.
 */
import {createHash} from "node:crypto";
import {readFileSync, writeFileSync} from "node:fs";
import {dirname, join} from "node:path";
import {fileURLToPath} from "node:url";

import Ajv2020 from "ajv/dist/2020.js";
import standaloneCode from "ajv/dist/standalone/index.js";
import addFormats from "ajv-formats";
import {_} from "ajv/dist/compile/codegen/index.js";

const here = dirname(fileURLToPath(import.meta.url));
const schemaPath = join(here, "../src/lib/content/validation/lesson.schema.generated.json");
const outPath = join(here, "../src/lib/content/validation/lesson-schema-validator.standalone.mjs");

const schemaText = readFileSync(schemaPath, "utf-8");
const schemaHash = createHash("sha256").update(schemaText).digest("hex");
const schema = JSON.parse(schemaText);

const ajv = new Ajv2020.default({
    allErrors: true,
    strict: false,
    code: {source: true, esm: true, formats: _`require("ajv-formats/dist/formats").fullFormats`},
});
addFormats.default(ajv);
const validate = ajv.compile(schema);
const rawModuleCode = standaloneCode.default(ajv, validate);

/**
 * Hoist Ajv's inline runtime requires (`const x = require("mod")[.default];`)
 * to top-level ESM imports so the output is native ESM. A deep, extension-less
 * specifier (e.g. `ajv/dist/runtime/ucs2length`) gets a `.js` suffix so it
 * resolves under the browser/dev-server, Vite/Vitest, the prod bundler AND
 * plain Node ESM alike (ajv ships no `exports` map, so the deep path is open).
 */
const hoistedImports = [];
let moduleCode = rawModuleCode.replace(
    /const (\w+) = require\("([^"]+)"\)(\.default)?;/g,
    (_match, name, mod, isDefault) => {
        const spec = mod.includes("/") && !/\.[cm]?js$/.test(mod) ? `${mod}.js` : mod;
        // #2415 — a plain default import of these CJS runtime helpers is
        // interop-DEPENDENT: Vite's dev interop resolves it to
        // ``exports.default`` (the function), but Node ESM and the Rolldown
        // production bundle resolve it to the ``module.exports`` OBJECT, so
        // the built app threw ``(0 , T.default) is not a function`` on every
        // draft check. Hoist to a namespace import and pick the function
        // across BOTH interop shapes; fail loudly if neither matches.
        hoistedImports.push(
            isDefault
                ? `import * as ${name}$ns from "${spec}";\n` +
                  `const ${name} = [${name}$ns.default?.default, ${name}$ns.default, ${name}$ns]` +
                  `.find((candidate) => typeof candidate === "function") ?? ` +
                  `(() => { throw new TypeError("${spec}: no callable default export (interop drift, #2415)"); })();`
                : `import * as ${name} from "${spec}";`,
        );
        return "";
    },
);
if (moduleCode.includes("require(")) {
    // Fail closed: a surviving `require(` (e.g. an inline `ajv-formats` format
    // reference the hoist above does not match) would break the ESM output on
    // the dev server exactly as #2288. Better a loud generator failure than a
    // silent re-introduction of the bug.
    throw new Error(
        "generate-lesson-validator: un-hoisted require() in the ESM output — " +
            "the dev server would fail to load it (#2288). Extend the hoist before shipping.",
    );
}
moduleCode = `${hoistedImports.join("\n")}${hoistedImports.length ? "\n" : ""}${moduleCode}`;

const banner = `/* GENERATED by scripts/generate-lesson-validator.mjs - DO NOT EDIT.
 * Standalone (build-time-compiled) lesson-schema validator: no runtime
 * code generation, hence CSP-clean (#2205).
 * schema-source-sha256: ${schemaHash}
 * Regenerate: bun run generate:validator (runs inside make sync-schema).
 */
`;
writeFileSync(outPath, banner + moduleCode + "\n", "utf-8");
console.log(`written ${outPath}`);
console.log(`schema sha256 ${schemaHash}`);
